$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue';$root='C:\JudasValidation';$base='http://192.168.122.1:8872';$out="$root\M78ContinuationResults";$label='combined-v2';$name="m78-$label-moved-package"
function Upload($p,$n){Invoke-WebRequest -UseBasicParsing "$base/$n" -Method Post -InFile $p|Out-Null}
try{
 if(Test-Path "$out\$name.json"){throw 'Preserve old moved-package receipt'}
 $runtime=Get-Content "$out\m78-$label-runtime.json" -Raw|ConvertFrom-Json;$export=Get-Content "$out\m78-$label-export.json" -Raw|ConvertFrom-Json;$library=Get-Content "$out\m78-$label-library.json" -Raw|ConvertFrom-Json
 if($runtime.exitCode -ne 0 -or $export.exitCode -ne 0 -or $runtime.archiveSHA256 -ne $library.archiveSHA256 -or $export.archiveSHA256 -ne $library.archiveSHA256){throw 'Final native runtime/export prerequisite mismatch'}
 $package="$root\M78ContinuationPackage-$label";$moved="$root\M78ContinuationMoved-$label";if(Test-Path $moved){throw 'Preserve previous moved package'}
 if((Get-FileHash "$package\judas.exe").Hash.ToLower() -ne $runtime.executableSHA256){throw 'Packaged runtime is not the verified freshly linked runtime'}
 $adapters=@();foreach($n in @('opengl32.dll','libgallium_wgl.dll')){$source="$root\Build\Release\$n";$dest="$package\$n";if(Test-Path $dest){throw 'VM GL adapter unexpectedly preexists'};Copy-Item -LiteralPath $source -Destination $dest;if((Get-FileHash $source).Hash -ne (Get-FileHash $dest).Hash){throw 'VM GL adapter copy mismatch'};$adapters+=@{source=$source;path=$n;bytes=(Get-Item $dest).Length;sha256=(Get-FileHash $dest).Hash.ToLower()}}
 Move-Item -LiteralPath $package -Destination $moved
 $harness="$out\$label\moved-services.harness";Invoke-WebRequest -UseBasicParsing "$base/m78-continuation-moved-services.harness" -OutFile $harness;if((Get-FileHash $harness).Hash.ToLower() -ne '6f975418b9e6f0a2af2644c509bc98115be2407db0e8f0afae88d092e149ef1d'){throw 'Original services harness SHA mismatch'}
 $env:GALLIUM_DRIVER='llvmpipe';$env:JUDAS_TEST_SCRIPT=$harness;$env:JUDAS_ENGINE_ROOT='C:\JudasValidation\UnavailableEngineRoot';$env:TEMP="$out\temp";$env:TMP=$env:TEMP
 $options=@{FilePath="$moved\judas.exe";WorkingDirectory='C:\Windows\Temp';PassThru=$true;RedirectStandardOutput="$out\$name.stdout.log";RedirectStandardError="$out\$name.stderr.log"}
 $watch=[Diagnostics.Stopwatch]::StartNew();$process=Start-Process @options;[void]$process.Handle;if(!$process.WaitForExit(600000)){Stop-Process -Id $process.Id -Force;$exit='owned package timed out'}else{$process.Refresh();$exit=$process.ExitCode}
 $files=@();foreach($file in Get-ChildItem -LiteralPath $moved -Recurse -File){$files+=@{path=$file.FullName.Substring($moved.Length+1);bytes=$file.Length;sha256=(Get-FileHash $file.FullName).Hash.ToLower()}}
 @{scope='Fresh normal Windows export, single package moved to unrelated location, no-argument native launch from C:\Windows\Temp with unavailable engine root. VM software GL is separately identified; not physical hardware or human validation.';exitCode=$exit;seconds=$watch.Elapsed.TotalSeconds;archiveSHA256=$library.archiveSHA256;runtimeSHA256=$runtime.executableSHA256;movedPath=$moved;cwd='C:\Windows\Temp';arguments=@();environment=@{GALLIUM_DRIVER=$env:GALLIUM_DRIVER;JUDAS_ENGINE_ROOT=$env:JUDAS_ENGINE_ROOT;JUDAS_TEST_SCRIPT=$env:JUDAS_TEST_SCRIPT};harnessSHA256='6f975418b9e6f0a2af2644c509bc98115be2407db0e8f0afae88d092e149ef1d';vmGLAdapters=$adapters;packageFiles=$files;freeBytes=(Get-PSDrive C).Free}|ConvertTo-Json -Depth 6|Set-Content "$out\$name.json" -Encoding UTF8
 Upload "$out\$name.stdout.log" "$name.stdout.log";Upload "$out\$name.stderr.log" "$name.stderr.log";Upload "$out\$name.json" "$name.json"
}catch{$p="$out\$name-error.txt";[string]$_.Exception.Message|Set-Content $p;Upload $p "$name-error.txt";exit 1}
